noTwin.value:
color-mix(
    in srgb,
    var(--ds-surface-card) 68%,
    var(--ds-surface-canvas, var(--ds-surface-panel))
  )

color-mix(
    in srgb,
    var(--ds-table-header-bg, var(--ds-color-bg-secondary)) 72%,
    var(--ds-table-bg, var(--ds-color-bg-primary))
  )

color-mix(
    in srgb,
    var(--ds-table-header-bg, var(--ds-color-bg-secondary)) 82%,
    transparent
  )

color-mix(
    in srgb,
    var(
        --rt-premium-card-accent,
        var(--ds-signal-card-accent, var(--ds-color-primary))
      )
      5%,
    transparent
  )

color-mix(
    in srgb,
    var(
        --rt-premium-card-accent,
        var(--ds-signal-card-accent, var(--ds-color-primary))
      )
      8%,
    transparent
  )

linear-gradient(
      var(--ds-surface-card-grid-line) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      var(--ds-surface-card-grid-line) 1px,
      transparent 1px
    ),
    linear-gradient(
      115deg,
      transparent 0%,
      color-mix(in srgb, var(--ds-surface-card) 34%, transparent) 46%,
      transparent 66%
    )

linear-gradient(
      var(--ds-surface-card-grid-line) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      var(--ds-surface-card-grid-line) 1px,
      transparent 1px
    )

linear-gradient(
    180deg,
    color-mix(
      in srgb,
      var(--ds-control-surface) 96%,
      var(--rt-insight-accent, var(--ds-color-primary))
