    var(--ds-control-surface)
  )

color-mix(
    in srgb,
    var(--rt-insight-accent, var(--ds-color-primary)) 18%,
    var(--ds-color-border)
  )

var(--ds-card-shadow),
    0 18px 46px
      color-mix(
        in srgb,
        var(--rt-insight-accent, var(--ds-color-primary)) 7%,
        transparent
      )

color-mix(
    in srgb,
    var(--rt-insight-accent, var(--ds-color-primary)) 8%,
    transparent
  )

color-mix(
    in srgb,
    var(--rt-insight-accent, var(--ds-color-primary)) 10%,
    var(--ds-control-surface)
  )

color-mix(
    in srgb,
    var(--ds-color-info, var(--ds-color-primary)) 7%,
    transparent
  )

linear-gradient(
    180deg,
    color-mix(
      in srgb,
      var(--ds-surface-card) 94%,
      var(--ds-surface-canvas, var(--ds-surface-panel))
    ),
    color-mix(
      in srgb,
      var(--ds-surface-panel) 82%,
      var(--ds-surface-canvas, var(--ds-surface-panel))
    )
  )

linear-gradient(
    180deg,
    color-mix(
      in srgb,
      var(--ds-control-surface) 98%,
      var(--ds-color-primary) 2%
    ),
    color-mix(in srgb, var(--ds-surface-panel) 54%, var(--ds-control-surface))
  )

linear-gradient(
    180deg,
    var(--ds-surface-card) 0%,
    color-mix(in srgb, var(--ds-surface-panel) 34%, var(--ds-surface-card)) 100%
  )

color-mix(
    in srgb,
    var(--ds-surface-tone, var(--rt-surface-tone, var(--ds-color-primary))) 11%,
    var(--ds-color-border)
  )

linear-gradient(
    180deg,
    color-mix(
      in srgb,
      var(--ds-surface-card) 96%,
      var(--ds-surface-tone, var(--rt-surface-tone, var(--ds-color-primary))) 4%
