    color-mix(in srgb, var(--ds-surface-panel) 42%, var(--ds-surface-card))
  )

color-mix(
    in srgb,
    var(--ds-control-surface) 92%,
    var(--ds-surface-card-bg, var(--ds-color-bg-primary))
  )

color-mix(
    in srgb,
    var(--ds-surface-panel-bg, var(--ds-surface-panel)) 72%,
    var(--ds-surface-card-bg, var(--ds-surface-card))
  )

color-mix(
    in srgb,
    var(--ds-surface-card-bg, var(--ds-surface-card)) 94%,
    transparent
  )

color-mix(
    in srgb,
    var(--ds-color-info, var(--ds-color-secondary, var(--ds-color-primary))) 12%,
    var(--ds-control-surface)
  )

color-mix(
    in srgb,
    var(--ds-color-info, var(--ds-color-secondary, var(--ds-color-primary))) 24%,
    var(--ds-color-border)
  )
